static void UseDivuCycles(u32 dst, u32 src)
{
  int i;

  /* minimum cycle time */
  u32 mcycles = 76 * MUL;

  /* 16-bit divisor */
  src <<= 16;

  /* 16-bit dividend */
  for (i=0; i<15; i++)
  {
    /* check if carry bit set  */
    if ((s32) dst < 0)
    {
      /* shift dividend and apply divisor */
      dst <<= 1;
      dst -= src;
    }
    else
    {
      /* shift dividend and add two cycles */
      dst <<= 1;
      mcycles += (4 * MUL);

      if (dst >= src)
      {
        /* apply divisor and remove one cycle */
        dst -= src;
        mcycles -= 2 * MUL;
      }
    }
  }

  USE_CYCLES(mcycles);

  /* one 68K bus refresh cycle should be skipped if instruction processing time is longer than refresh period (128 CPU cycles on Mega Drive / Genesis) */
  if (mcycles >= (128*MUL))
  {
    REFRESH += (128*MUL);
  }
}

static void UseDivsCycles(s32 dst, s16 src)
{
  /* minimum cycle time */
  u32 mcycles = 12 * MUL;

  /* negative dividend */
  if (dst < 0) mcycles += 2 * MUL;

  if ((abs(dst) >> 16) < abs(src))
  {
    int i;

    /* absolute quotient */
    u32 quotient = abs(dst) / abs(src);

    /* add default cycle time */
    mcycles += (110 * MUL);

    /* positive divisor */
    if (src >= 0)
    {
      /* check dividend sign */
      if (dst >= 0) mcycles -= 2 * MUL;
      else mcycles += 2 * MUL;
    }

    /* check higher 15-bits of quotient */
    for (i=0; i<15; i++)
    {
      quotient >>= 1;
      if (!(quotient & 1)) mcycles += 2 * MUL;
    }
  }
  else
  {
    /* absolute overflow */
    mcycles += (4 * MUL);
  }

  USE_CYCLES(mcycles);
  
  /* one 68K bus refresh cycle should be skipped if instruction processing time is longer than refresh period (128 CPU cycles on Mega Drive / Genesis) */
  if (mcycles >= (128*MUL))
  {
    REFRESH += (128*MUL);
  }
}

static void UseMuluCycles(u16 src)
{
  /* minimum cycle time */
  u32 mcycles = 38 * MUL;

  /* count number of bits set to 1 */
  while (src)
  {
    if (src & 1) mcycles += (2 * MUL);
    src >>= 1;
  }

  /* 38 + 2*N */
  USE_CYCLES(mcycles);
}

static void UseMulsCycles(s16 src)
{
  /* minimum cycle time */
  u32 mcycles = 38 * MUL;

  /* detect 01 or 10 patterns */
  s32 tmp = src << 1;
  tmp = (tmp ^ src) & 0xFFFF;

  /* count number of bits set to 1 */
  while (tmp)
  {
    if (tmp & 1) mcycles += (2 * MUL);
    tmp >>= 1;
  }

  /* 38 + 2*N */
  USE_CYCLES(mcycles);
}

